def next_prime(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        d = 3
        while d * d <= x:
            if x % d == 0:
                return False
            d += 2
        return True
    cand = n + 1
    while not is_prime(cand):
        cand += 1
    return cand

def date_n_days_before_year_end(year, n):
    leap = (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)
    month_lengths = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    day_of_year = (366 if leap else 365) - n
    month = 0
    while day_of_year > month_lengths[month]:
        day_of_year -= month_lengths[month]
        month += 1
    return (month + 1, day_of_year)

