def count_weekday_occurrences_in_month(year, month, weekday_num):
    def is_leap_year(y):
        return (y % 4 == 0 and y % 100 != 0) or y % 400 == 0
    def days_before_year(y):
        y -= 1
        return 365 * y + y // 4 - y // 100 + y // 400
    def days_before_month(y, m):
        lengths = [31, 29 if is_leap_year(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return sum(lengths[:m - 1])
    month_lengths = [31, 29 if is_leap_year(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    num_days = month_lengths[month - 1]
    day1_number = days_before_year(year) + days_before_month(year, month) + 1
    day1_weekday = (day1_number - 1) % 7
    count = 0
    for d in range(1, num_days + 1):
        if (day1_weekday + d - 1) % 7 == weekday_num:
            count += 1
    return count

