def compress_runs_min_length(s, min_run):
    if not s:
        return ''
    parts = []
    start = 0
    for i in range(1, len(s) + 1):
        if i == len(s) or s[i] != s[start]:
            run = s[start:i]
            if len(run) >= min_run:
                parts.append(run[0] + str(len(run)))
            else:
                parts.append(run)
            start = i
    return ''.join(parts)

